@@ -76,8 +76,8 @@ impl UnixStream {
     pub fn connect(path: impl AsRef<UdsPath>) -> Connect<'_> {
         let path = path.as_ref();

-        let socket = if path.is_abstract() {
-            StdSocketAddr::from_abstract_name(path.as_abstract_name().unwrap())
+        let socket = if path.is_abstract() {
+            StdSocketAddr::from_abstract_name(path.as_abstract_name().unwrap().strip_prefix('\0').unwrap())
         } else {
             StdSocketAddr::from_pathname(path.as_pathname().unwrap())
         };
